using System; using System.IO; using System.ComponentModel; using System.Linq; using System.Threading.Tasks; using WinsockPacketEditor;
static class ExportSnapshotOracle {
 public static int Run(string[] a) { var list=new BindingList<PacketInfo>(); Operate.SendConfig.Send.AddSendCollection(list,17,Operate.PacketConfig.Packet.PacketType.TCP_Req,"from","to",new byte[]{1,2}); var host=new Host(list[0],a[0]); UI.Attach(host,null); Operate.SendConfig.Send.SaveSendCollection_Dialog("",list.ToList()).GetAwaiter().GetResult(); var xml=File.ReadAllText(a[0]); Console.WriteLine(xml); if(!xml.Contains("<Socket>99</Socket>")||!xml.Contains("<Buffer>AA BB</Buffer>"))throw new Exception("Unexpected original snapshot behavior"); Console.WriteLine("PASS: original file-dialog callback edit is included in exported shallow snapshot"); return 0; }
 sealed class Host:IUiHost { PacketInfo packet; string path; public Host(PacketInfo p,string f){packet=p;path=f;} public Task<bool> ConfirmAsync(string t,string c,UiIcon i=UiIcon.Warn){return Task.FromResult(true);} public void Notify(UiIcon i,string t,string c=null){Console.WriteLine("Notify "+i+": "+t);} public void Toast(UiIcon i,string t){} public Task<string> PickOpenAsync(FilePick p){return Task.FromResult<string>(null);} public Task<string> PickSaveAsync(FilePick p){packet.PacketSocket=99;packet.PacketBuffer=new byte[]{0xAA,0xBB};return Task.FromResult(path);} public Task<T> BusyAsync<T>(string t,Func<T> f){return Task.FromResult(f());} public Task<T> PromptAsync<T>(string f,object a)where T:class{return Task.FromResult<T>(null);} }
}
